"""
Runs the five required synthetic cases and writes real outputs to
../evidence/case_results.md. All data is SYNTHETIC (evidence category E-09).
Run from the prototype/ directory: python run_cases.py
"""
from resultflow import ResultFlow
from test_resultflow import USERS, at_approval
from pathlib import Path

out = [
    "# Five synthetic cases -- actual outputs (generated by run_cases.py; synthetic data)",
    "",
    "| # | Scenario | Actual result |",
    "|---|---|---|",
]

CK = ("SYN-S-1", "SYN-CS101")   # (student, course) key used by effective_grades and placement

# ── Case 1: Normal ────────────────────────────────────────────────────────────
rf = ResultFlow(dict(USERS))
k  = at_approval(rf)
status = rf.publish("SYN-A-1", k, "B")
out.append(
    "| 1 Normal | approver publishes verified result"
    " | status={}, sync_status={}, effective_grade={}, placement={} |".format(
        status,
        rf.attempts[k]["sync_status"],
        rf.effective_grades.get(CK),
        rf.placement.get(CK),
    )
)

# ── Case 2: Missing information ───────────────────────────────────────────────
rf = ResultFlow(dict(USERS))
r1 = rf.register("SYN-E-1", "SYN-S-1", "",          "repeat",  "2026-07-24")
r2 = rf.register("SYN-E-1", "SYN-S-1", "SYN-CS101", "invalid", "2026-07-24")
out.append(
    "| 2 Missing info | empty course / invalid type"
    " | {}/{} ; attempts stored={} |".format(r1, r2, len(rf.attempts))
)

# ── Case 3: Duplicate ─────────────────────────────────────────────────────────
rf = ResultFlow(dict(USERS))
k  = at_approval(rf)
rf.publish("SYN-A-1", k, "B")
dup = rf.register("SYN-E-1", "SYN-S-1", "SYN-CS101", "grade_improvement", "2026-07-24")
out.append(
    "| 3 Duplicate | same attempt key submitted twice"
    " | {} ; attempts stored={} ; grade unchanged={} |".format(
        dup, len(rf.attempts), rf.attempts[k]["published_grade"]
    )
)

# ── Case 4: Unauthorized ──────────────────────────────────────────────────────
other  = rf.view("SYN-S-2", "SYN-S-1")
emp    = rf.view("SYN-C-1", "SYN-S-1")
own    = rf.view("SYN-S-1", "SYN-S-1")
denials = sum(r["event"] == "DENIED_VIEW" for r in rf.audit)
out.append(
    "| 4 Unauthorized | other student / unconsented employer / own record"
    " | other={} employer={} own returned={} ; denials logged={} |".format(
        other, emp, bool(own), denials
    )
)

# ── Case 5: Failed step and recovery ─────────────────────────────────────────
rf = ResultFlow(dict(USERS))
k  = at_approval(rf)
rf.sync_fault = True
rf.publish("SYN-A-1", k, "B")
before = "status={} sync_status={} effective_grade={} in_placement={}".format(
    rf.attempts[k]["status"],
    rf.attempts[k]["sync_status"],
    rf.effective_grades.get(CK),
    CK in rf.placement,
)
rf.sync_fault = False
retry_result  = rf.retry_sync("SYN-X-1", k)
after = "after retry sync_status={} placement={} audit_valid={}".format(
    retry_result,
    rf.placement.get(CK),
    rf.verify_audit(),
)
out.append(
    "| 5 Failed step | sync fails after approval then retried"
    " | {} ; {} |".format(before, after)
)

# ── Write file ────────────────────────────────────────────────────────────────
evidence_path = Path(__file__).resolve().parent.parent / "evidence" / "case_results.md"
evidence_path.write_text("\n".join(out) + "\n", encoding="utf-8")
print("\n".join(out))
